<style>
    .fi-header{display:none!important}.orion-fa-inner,.orion-fa-inner *{box-sizing:border-box;font-family:'Cairo',sans-serif}.orion-fa-inner{--fi-panel:#0c1728;--fi-border:#22334f;--fi-soft:#17263c;--fi-text:#eef3fa;--fi-muted:#71839d;direction:rtl;color:var(--fi-text);padding-bottom:22px}.fai-hero{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:14px;padding:15px 16px;border-radius:14px;border:1px solid var(--fi-border);background:linear-gradient(145deg,#0e192b,#0a1423);box-shadow:0 18px 44px rgba(0,0,0,.13)}.fai-hero-main{display:flex;align-items:center;gap:12px;min-width:0}.fai-icon{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;color:#c4b5fd;border:1px solid rgba(139,92,246,.36);background:linear-gradient(145deg,rgba(124,58,237,.25),rgba(76,29,149,.1));flex:none}.fai-icon svg{width:22px;height:22px}.fai-eyebrow{font-size:7px;font-weight:950;letter-spacing:1.6px;color:#806be4}.fai-title{margin-top:3px;font-size:19px;font-weight:950;color:#f3f6fb}.fai-sub{margin-top:4px;font-size:8px;color:#687a94;line-height:1.7}.fai-chips{display:flex;align-items:center;justify-content:flex-end;gap:6px;flex-wrap:wrap}.fai-chip{min-height:28px;display:inline-flex;align-items:center;gap:6px;padding:0 9px;border-radius:999px;border:1px solid #273a58;background:#101c2f;color:#9aabc0;font-size:8px;font-weight:900}.fai-chip strong{color:#dfe7f2}.fai-chip.green{border-color:rgba(52,211,153,.25);background:rgba(52,211,153,.07);color:#67ddb2}.fai-chip.red{border-color:rgba(251,113,133,.25);background:rgba(251,113,133,.07);color:#fb8b9e}.fai-chip.amber{border-color:rgba(251,191,36,.22);background:rgba(251,191,36,.06);color:#f3c852}.fai-chip.blue{border-color:rgba(96,165,250,.24);background:rgba(96,165,250,.06);color:#78b5fa}.fai-dot{width:5px;height:5px;border-radius:50%;background:currentColor;box-shadow:0 0 9px currentColor}.fai-content{border:1px solid var(--fi-border);border-radius:14px;padding:14px;background:linear-gradient(145deg,#0b1524,#091321)}
    .orion-fa-inner .fi-section{border:1px solid #22334f!important;background:#0d1829!important;box-shadow:none!important;border-radius:12px!important;overflow:hidden!important}.orion-fa-inner .fi-section-header{border-bottom:1px solid #1a2a40!important;background:#101c2f!important}.orion-fa-inner .fi-section-header-heading{font-size:10px!important;font-weight:950!important;color:#e6edf7!important}.orion-fa-inner .fi-section-header-description{font-size:8px!important;color:#687a94!important}.orion-fa-inner .fi-input-wrp{background:#0b1626!important;border-color:#263a59!important;box-shadow:none!important}.orion-fa-inner input,.orion-fa-inner textarea,.orion-fa-inner select{color:#dfe7f2!important}.orion-fa-inner .fi-fo-field-wrp-label{font-size:8px!important;color:#8a9ab0!important;font-weight:850!important}.orion-fa-inner .fi-btn{font-size:9px!important;font-weight:900!important;border-radius:9px!important}.orion-fa-inner .fi-btn-color-primary{background:linear-gradient(135deg,#7047e8,#8b5cf6)!important}.orion-fa-inner .fi-form-actions{border-top:1px solid #1b2a40!important;padding-top:13px!important}
    @media(max-width:800px){.fai-hero{align-items:flex-start;flex-direction:column}.fai-chips{justify-content:flex-start}.fai-content{padding:10px}}@media(max-width:520px){.fai-title{font-size:16px}}
